package io.github.diodeme.ji.artifact;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;

import io.github.diodeme.ji.error.ErrorCode;
import org.junit.jupiter.api.Test;

final class ArtifactErrorsTest {
    @Test
    void publicErrorsUseVersionedCatalogAndContainNoRawContent() {
        var error = ArtifactErrors.hashMismatch("a".repeat(64), "b".repeat(64)).error();
        assertEquals(ErrorCode.ARTIFACT_HASH_MISMATCH, error.code());
        assertEquals("a".repeat(64), error.parameters().get("expectedSha256"));
        assertFalse(error.parameters().containsKey("bytes"));
        assertFalse(error.traceId().isPresent());
    }
}
